#!/usr/bin/env python3
"""Local extraction and narrow quote validation; requires pypdf."""
import argparse
import csv
import json
import re
from pathlib import Path


def normalize(text):
    return re.sub(r"\s+", " ", text).strip()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("pdf_folder", type=Path)
    parser.add_argument("ledger", type=Path)
    args = parser.parse_args()
    try:
        from pypdf import PdfReader
    except ImportError:
        parser.exit(2, "Missing dependency: install pypdf in your local Python environment. No PDFs checked.\n")
    if not args.pdf_folder.is_dir():
        parser.exit(2, "PDF folder is missing. No PDFs checked.\n")
    pages, issues, errors = {}, [], []
    files = sorted(p for p in args.pdf_folder.rglob("*") if p.suffix.lower() == ".pdf" and p.is_file())
    if not files:
        issues.append("No PDFs found")
    for path in files:
        name = path.relative_to(args.pdf_folder).as_posix()
        try:
            reader = PdfReader(path)
            if reader.is_encrypted and not reader.decrypt(""):
                raise ValueError("encrypted PDF requires a password")
            for number, page in enumerate(reader.pages, 1):
                try:
                    text = page.extract_text() or ""
                    if not normalize(text):
                        issues.append(f"{name}, page {number}: no readable text; inspect visually or verify OCR")
                    else:
                        pages[(name, number)] = normalize(text)
                except Exception as exc:
                    issues.append(f"{name}, page {number}: extraction failed ({type(exc).__name__})")
        except Exception as exc:
            issues.append(f"{name}: unreadable PDF ({type(exc).__name__})")
    with args.ledger.open(encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(handle)
        expected = ["citation", "page", "quoted passage", "claim", "limitation"]
        if reader.fieldnames != expected:
            errors.append("CSV headers must be: " + ",".join(expected))
        else:
            for row_number, row in enumerate(reader, 2):
                try:
                    page_number = int(row["page"])
                    text = pages.get((row["citation"], page_number))
                    quote = normalize(row["quoted passage"])
                    if not text:
                        errors.append(f"Row {row_number}: missing citation/page or unreadable page")
                    elif not quote or quote not in text:
                        errors.append(f"Row {row_number}: quote absent from cited page")
                    if not row["claim"].startswith(("Source claim:", "Interpretation:")):
                        errors.append(f"Row {row_number}: label claim type")
                    if not row["limitation"].strip() or None in row:
                        errors.append(f"Row {row_number}: malformed row or missing limitation")
                except (ValueError, TypeError, AttributeError):
                    errors.append(f"Row {row_number}: invalid fields or page number")
    print(json.dumps({"checked_pdfs": len(files), "readable_pages": len(pages), "issues": issues, "errors": errors}, indent=2))
    return 1 if errors else 0


if __name__ == "__main__":
    raise SystemExit(main())

